('210', 'Mint Green Ikat Kurta Set with Embellished Ivory Nehru Jacket', 'mint-green-ikat-kurta-ivory-nehru-jacket', 'MSW-07-IKT', 'Handwoven Ikat Silk & Textured Matka Silk | Mint Green & Cream Ivory', 'Mens wear', 'A crisp mint green ikat printed kurta paired with a rich ivory textured bundi jacket detailed with delicate hand embroidery along the collar and welt pocket.', 'Handwoven Ikat Silk & Textured Matka Silk', 'Mirror Work Collar & Pocket Border with Geometric Weave', 'Mint Green & Cream Ivory', 'uploads/collections/mens wear/mint-green-ikat-kurta-ivory-nehru-jacket/sri shinghar indoor_59198 copy.jpg', NULL, '0', '6', 'published', '2026-09-01 22:54:49', '2026-09-01 22:54:49'),
('211', 'Sunshine Yellow Resham & Mirror Embroidered Kurta Set', 'sunshine-yellow-embroidered-kurta-set', 'MSW-08-YEL', 'Chanderi Silk Blend | Sunshine Yellow & Antique Gold', 'Mens wear', 'A radiant sunshine yellow kurta set featuring intricate tone-on-tone resham embroidery and delicate mirror work across the placket, collar, and cuffs.', 'Chanderi Silk Blend', 'Tone-on-tone Resham Threadwork & Delicate Mirror Embroidery', 'Sunshine Yellow & Antique Gold', 'uploads/collections/mens wear/sunshine-yellow-embroidered-kurta-set/sri shinghar indoor_59327 copy (2).jpg', NULL, '0', '7', 'published', '2026-09-01 22:54:49', '2026-09-01 22:54:49'),
('212', 'Emerald Sea Kurta with Midnight Navy Brocade Bandi', 'emerald-sea-kurta-midnight-navy-bandi', 'MSW-09-NVY', 'Pure Raw Silk & Brocade | Emerald Sea Green & Midnight Navy', 'Mens wear', 'A vibrant jewel-toned sea green kurta tailored with a rich midnight blue all-over geometric motif bandi jacket featuring signature crest pocket embroidery.', 'Pure Raw Silk & Brocade', 'Golden Buti Weaving with Embroidered Crest Pocket', 'Emerald Sea Green & Midnight Navy', 'uploads/collections/mens wear/emerald-sea-kurta-midnight-navy-bandi/sri shinghar indoor_59385 copy.jpg', NULL, '0', '8', 'published', '2026-09-01 22:54:49', '2026-09-01 22:54:49'),
('213', 'Rust Striped Kurta with Navy Floral Bandi & Dhoti Set', 'rust-striped-kurta-navy-floral-bandi-dhoti', 'MSW-10-DHT', 'Textured Cotton Silk & Raw Silk | Rust Terracotta & Navy Blue', 'Mens wear', 'An opulent traditional festive ensemble pairing a terracotta striped kurta and navy dhoti pants with a luxurious navy blue jacket covered in blooming floral embroidery.', 'Textured Cotton Silk & Raw Silk', 'Multi-Color Floral Embroidery with Gota Trim Border', 'Rust Terracotta & Navy Blue', 'uploads/collections/mens wear/rust-striped-kurta-navy-floral-bandi-dhoti/sri shinghar indoor_59453 copy (2).jpg', NULL, '0', '9', 'published', '2026-09-01 22:54:49', '2026-09-01 22:54:49'),
('214', 'Royal Ivory & Gold Mirror Work Groom Sherwani', 'royal-ivory-gold-mirror-work-sherwani', 'MSW-11-SHR', 'Raw Silk & Georgette | Pale Gold & Ivory', 'Mens wear', 'A magnificent royal groom\'s sherwani adorned with all-over intricate jaal geometric mirror work and resham embroidery, accessorized with a multi-layered royal kundan mala.', 'Raw Silk & Georgette', 'Intricate All-over Resham Threadwork & Mirror Embroidery', 'Pale Gold & Ivory', 'uploads/collections/mens wear/royal-ivory-gold-mirror-work-sherwani/sri shinghar indoor_59649 copy.jpg', NULL, '0', '10', 'published', '2026-09-01 22:54:49', '2026-09-01 22:54:49'),
('215', 'Mens wear Curated Style', 'mens-wear-style-1788281225', 'MEN-360', 'Custom | Various', 'Mens wear', 'Curated piece from collection photoshoot.', 'Custom', 'Custom Detailing', 'Various', 'uploads/collections/mens wear/mens-wear-style-1788281225/sri shinghar indoor_58824 copy (2).jpg', NULL, '0', '11', 'published', '2026-09-01 22:54:49', '2026-09-01 22:54:49');
